MAIN_POPULATIONS = {'ferry_yard': 1200, 'shared_keys': 3000, 'open_house': 6000,
                    'new_purpose': 10000, 'lights_evening': 20000, 'home': 20000}


def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode()).hexdigest()


def fields(value):
    return sorted(f for _, f, _, _ in string.Formatter().parse(value) if f is not None)


def append_unique(target, entries, key):
    existing = {e[key]: e for e in target}
    if len(existing) != len(target):
        raise ValueError('Duplicate existing ' + key)
    for entry in entries:
        identity = entry[key]
        if identity in existing:
            if existing[identity] != entry:
                raise ValueError('Existing authored content differs: ' + identity)
        else:
            target.append(entry)
            existing[identity] = entry


def correct_existing_saint_invitation(data, catalogs):
    """Repair only the exact first-authored Saint invitation reward mismatch.

    The nine older cities and all their localized text entries remain untouched.
    Any independently edited Saint invitation is rejected before writing.
    """
    key = 'campaign.saint_mary_ville_body'
    city = next((c for c in data['cities'] if c['id'] == CITY), None)
    if city is not None:
        reward = (city['bridgeMoney'], city['bridgeCards'])
        if reward not in ((15000, 8), (12500, 7)):
            raise ValueError('Unexpected Saint Mary Ville invitation reward.')
        city.update(bridgeMoney=12500, bridgeCards=7)
    replacements = {
        'de': ('Mit 12.500 Geld und 7 Teamkarten', 'Mit 15.000 Geld und 8 Teamkarten'),
        'en': ('With 12,500 money and 7 team cards', 'With 15,000 money and 8 team cards'),
        'es': ('Con 12.500 de dinero y 7 cartas de equipo', 'Con 15.000 de dinero y 8 cartas de equipo'),
        'fr': ('Avec 12 500 d’argent et 7 cartes d’équipe', 'Avec 15 000 d’argent et 8 cartes d’équipe'),
        'ru': ('С 12 500 денег и 7 карточками команды', 'С 15 000 денег и 8 карточками команды'),
    }

    def correct(entries, language, field):
        entry = next((e for e in entries if e['key'] == key), None)
        if entry is None:
            return
        current = TEXT[key][language]
        previous = current.replace(*replacements[language])
        if entry[field] not in (previous, current):
            raise ValueError('Unexpected edited Saint Mary Ville invitation: ' + language)
        entry[field] = current

    correct(data['texts'], 'de', 'de')
    for lang in LANGUAGES:
        correct(catalogs[lang]['entries'], lang, 'value')


def author():
    data = json.loads(PATH.read_text(encoding='utf-8-sig'))
    catalogs = {lang: json.loads((LOCALES / (lang + '.json')).read_text(encoding='utf-8-sig')) for lang in LANGUAGES}
    before, before_catalogs = copy.deepcopy(data), copy.deepcopy(catalogs)
